<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Conway's Cosmic Garden</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090b18;
      --panel: #14182b;
      --panel-light: #202644;
      --text: #f5f7ff;
      --muted: #aab1ce;
      --cyan: #62f5d2;
      --purple: #b98cff;
      --pink: #ff78b7;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-width: 440px;
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      overflow: auto;
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 15% 15%, #29205a 0, transparent 27rem),
        radial-gradient(circle at 85% 80%, #153d4b 0, transparent 28rem),
        var(--bg);
    }

    main {
      width: max-content;
      max-width: 100%;
      text-align: center;
    }

    h1 {
      margin: 0 0 4px;
      font-size: clamp(1.75rem, 4vw, 2.65rem);
      letter-spacing: -0.04em;
    }

    .subtitle {
      margin: 0 0 18px;
      color: var(--muted);
    }

    .game-shell {
      padding: 14px;
      border: 1px solid #394064;
      border-radius: 24px;
      background: color-mix(in srgb, var(--panel) 92%, transparent);
      box-shadow:
        0 24px 80px #0009,
        inset 0 1px 0 #ffffff12;
    }

    #life {
      display: block;
      width: 600px;
      height: 600px;
      min-width: 400px;
      min-height: 400px;
      border: 2px solid #4a527d;
      border-radius: 15px;
      background: #090d19;
      box-shadow:
        inset 0 0 35px #000,
        0 0 30px #62f5d21a;
      cursor: crosshair;
      touch-action: none;
      user-select: none;
    }

    .toolbar {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 9px;
      margin-top: 14px;
    }

    button {
      min-width: 104px;
      border: 1px solid #4a537c;
      border-radius: 999px;
      padding: 10px 16px;
      color: var(--text);
      font: 700 0.94rem/1 system-ui, sans-serif;
      background: linear-gradient(180deg, var(--panel-light), #171b31);
      box-shadow: 0 5px 13px #0005, inset 0 1px 0 #ffffff17;
      cursor: pointer;
      transition: transform 120ms ease, border-color 120ms ease, filter 120ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      border-color: var(--purple);
      filter: brightness(1.14);
    }

    button:active {
      transform: translateY(1px) scale(0.98);
    }

    #play.running {
      color: #071713;
      border-color: var(--cyan);
      background: linear-gradient(180deg, #82ffe2, #48d2b2);
    }

    .status {
      min-height: 1.4em;
      margin: 13px 0 1px;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .status strong {
      color: var(--cyan);
    }
  </style>
</head>
<body>
  <main>
    <h1>Conway's Cosmic Garden ✨</h1>
    <p class="subtitle">Click or drag to plant stars, then watch them evolve.</p>

    <section class="game-shell" aria-label="Conway's Game of Life">
      <canvas
        id="life"
        width="600"
        height="600"
        aria-label="60 by 60 Game of Life grid"
      ></canvas>

      <div class="toolbar">
        <button id="step" type="button">👣 Step</button>
        <button id="play" type="button">▶ Play</button>
        <button id="random" type="button">🎲 Random</button>
        <button id="clear" type="button">🧹 Clear</button>
      </div>

      <p class="status">
        Generation <strong id="generation">0</strong>
        · <span id="population">0</span> living cells
      </p>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const W = 60;
      const H = 60;
      const canvas = document.getElementById("life");
      const ctx = canvas.getContext("2d");
      const generationLabel = document.getElementById("generation");
      const populationLabel = document.getElementById("population");
      const playButton = document.getElementById("play");

      let cells = new Uint8Array(W * H);
      let generation = 0;
      let timer = null;
      let painting = false;
      let paintValue = 1;
      let lastPainted = -1;

      const index = (x, y) => y * W + x;

      function inBounds(x, y) {
        return Number.isInteger(x) &&
               Number.isInteger(y) &&
               x >= 0 && x < W &&
               y >= 0 && y < H;
      }

      function get(x, y) {
        return inBounds(x, y) ? cells[index(x, y)] : 0;
      }

      function draw() {
        const cellWidth = canvas.width / W;
        const cellHeight = canvas.height / H;

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#090d19";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.beginPath();
        ctx.strokeStyle = "rgba(132, 146, 190, 0.105)";
        ctx.lineWidth = 1;

        for (let x = 1; x < W; x++) {
          const px = Math.round(x * cellWidth) + 0.5;
          ctx.moveTo(px, 0);
          ctx.lineTo(px, canvas.height);
        }

        for (let y = 1; y < H; y++) {
          const py = Math.round(y * cellHeight) + 0.5;
          ctx.moveTo(0, py);
          ctx.lineTo(canvas.width, py);
        }
        ctx.stroke();

        ctx.save();
        ctx.fillStyle = "#68f6d4";
        ctx.shadowColor = "#62f5d2";
        ctx.shadowBlur = 7;

        let population = 0;
        for (let y = 0; y < H; y++) {
          for (let x = 0; x < W; x++) {
            if (cells[index(x, y)]) {
              population++;
              ctx.fillRect(
                x * cellWidth + 1.5,
                y * cellHeight + 1.5,
                Math.max(1, cellWidth - 3),
                Math.max(1, cellHeight - 3)
              );
            }
          }
        }
        ctx.restore();

        generationLabel.textContent = generation;
        populationLabel.textContent = population;
      }

      function set(x, y, value) {
        if (!inBounds(x, y)) return;
        cells[index(x, y)] = value ? 1 : 0;
        draw();
      }

      function step() {
        // Every result is written to a separate array, ensuring that all
        // cells in this generation are derived from the same current state.
        const next = new Uint8Array(W * H);

        for (let y = 0; y < H; y++) {
          for (let x = 0; x < W; x++) {
            let neighbors = 0;

            for (let dy = -1; dy <= 1; dy++) {
              for (let dx = -1; dx <= 1; dx++) {
                if (dx !== 0 || dy !== 0) {
                  neighbors += get(x + dx, y + dy);
                }
              }
            }

            const alive = cells[index(x, y)] === 1;
            next[index(x, y)] =
              neighbors === 3 || (alive && neighbors === 2) ? 1 : 0;
          }
        }

        cells = next;
        generation++;
        draw();
      }

      function clear() {
        cells.fill(0);
        generation = 0;
        draw();
      }

      function randomize() {
        for (let i = 0; i < cells.length; i++) {
          cells[i] = Math.random() < 0.27 ? 1 : 0;
        }
        generation = 0;
        draw();
      }

      function togglePlay() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
          playButton.textContent = "▶ Play";
          playButton.classList.remove("running");
          playButton.setAttribute("aria-pressed", "false");
        } else {
          timer = setInterval(step, 110);
          playButton.textContent = "⏸ Pause";
          playButton.classList.add("running");
          playButton.setAttribute("aria-pressed", "true");
        }
      }

      function eventCell(event) {
        const rect = canvas.getBoundingClientRect();
        return {
          x: Math.floor((event.clientX - rect.left) / rect.width * W),
          y: Math.floor((event.clientY - rect.top) / rect.height * H)
        };
      }

      function paint(event) {
        const { x, y } = eventCell(event);
        if (!inBounds(x, y)) return;

        const i = index(x, y);
        if (i === lastPainted) return;

        cells[i] = paintValue;
        lastPainted = i;
        draw();
      }

      canvas.addEventListener("pointerdown", event => {
        event.preventDefault();
        const { x, y } = eventCell(event);
        if (!inBounds(x, y)) return;

        painting = true;
        paintValue = get(x, y) ? 0 : 1;
        lastPainted = -1;
        canvas.setPointerCapture(event.pointerId);
        paint(event);
      });

      canvas.addEventListener("pointermove", event => {
        if (painting) paint(event);
      });

      function stopPainting() {
        painting = false;
        lastPainted = -1;
      }

      canvas.addEventListener("pointerup", stopPainting);
      canvas.addEventListener("pointercancel", stopPainting);
      canvas.addEventListener("lostpointercapture", stopPainting);

      document.getElementById("step").addEventListener("click", step);
      document.getElementById("play").addEventListener("click", togglePlay);
      document.getElementById("random").addEventListener("click", randomize);
      document.getElementById("clear").addEventListener("click", clear);

      window.life = {
        w: W,
        h: H,
        get,
        set,
        step,
        clear
      };

      playButton.setAttribute("aria-pressed", "false");
      draw();
    })();
  </script>
</body>
</html>
